export function initMediaAdmin(){
 const form=document.querySelector('#hero-media-upload');if(!form)return;
 const input=form.elements.video,button=form.querySelector('button[type=submit]'),status=document.querySelector('#hero-media-status'),current=document.querySelector('#hero-media-current'),progress=document.querySelector('#hero-media-progress'),preview=document.querySelector('#hero-media-preview');
 let localPreview,storageReady=false,previewInvalid=false;
 const size=n=>(n/1024/1024).toLocaleString('pt-BR',{maximumFractionDigits:1})+' MB';
 async function refresh(){const response=await fetch('/api/admin/midia/chamada',{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível consultar o vídeo.');current.replaceChildren();if(data.configurado){const label=document.createElement('p');label.textContent='Publicado: '+data.nome+' · '+size(data.tamanho)+' · '+new Date(data.atualizado_em).toLocaleString('pt-BR');const link=document.createElement('a');link.className='text-button';link.href='/';link.target='_blank';link.rel='noopener';link.textContent='Ver a chamada no site';current.append(label,link);}else current.textContent='O vídeo ilustrativo anterior permanece no site até você publicar um novo arquivo.';storageReady=!!data.armazenamento_disponivel;button.disabled=!storageReady||previewInvalid;return data;}
 preview.addEventListener('error',()=>{if(!preview.getAttribute('src'))return;previewInvalid=true;button.disabled=true;status.textContent='Este navegador não conseguiu abrir a prévia. Exporte o vídeo como MP4 H.264 com áudio AAC antes de publicar.';});preview.addEventListener('loadedmetadata',()=>{previewInvalid=false;button.disabled=!storageReady;const w=preview.videoWidth,h=preview.videoHeight;document.querySelector('#hero-media-dimensions').textContent=w+' × '+h+' px · '+(Math.abs(w/h-16/9)<.04?'Formato horizontal 16:9, recomendado para a abertura.':'O vídeo será exibido inteiro. As laterais serão preenchidas por um fundo desfocado da própria cena.');});
 input.addEventListener('change',()=>{previewInvalid=false;button.disabled=!storageReady;if(localPreview)URL.revokeObjectURL(localPreview);const file=input.files[0];status.textContent='';document.querySelector('#hero-media-dimensions').textContent='';preview.hidden=!file;if(!file)return;if(!/\.mp4$/i.test(file.name)||(file.type&&file.type!=='video/mp4')){status.textContent='Escolha um arquivo MP4.';input.value='';preview.hidden=true;return;}if(file.size>100*1024*1024){status.textContent='O arquivo ultrapassa 100 MB. Exporte uma versão menor antes de enviar.';input.value='';preview.hidden=true;return;}localPreview=URL.createObjectURL(file);preview.src=localPreview;preview.load();status.textContent='Prévia local: '+file.name+' · '+size(file.size)+'. O site só muda após publicar.';});
 form.addEventListener('submit',event=>{event.preventDefault();const file=input.files[0];if(!file)return;if(previewInvalid){status.textContent='Corrija o formato do vídeo antes de publicar.';return;}if(file.size>100*1024*1024){status.textContent='Escolha um vídeo de até 100 MB.';return;}if(!form.reportValidity())return;button.disabled=true;input.disabled=true;progress.hidden=false;progress.value=0;status.textContent='Enviando o vídeo diretamente para o armazenamento do site…';
  const xhr=new XMLHttpRequest();xhr.open('PUT','/api/admin/midia/chamada');xhr.setRequestHeader('Content-Type','video/mp4');xhr.setRequestHeader('X-File-Name',encodeURIComponent(file.name));xhr.upload.onprogress=event=>{if(event.lengthComputable){progress.value=Math.round(100*event.loaded/event.total);status.textContent='Enviando: '+progress.value+'%. Aguarde a confirmação de publicação.';}};
  const release=()=>{button.disabled=!storageReady||previewInvalid;input.disabled=false;progress.hidden=true;};
  xhr.onload=async()=>{let data;try{data=JSON.parse(xhr.responseText);}catch{data={error:'Não foi possível confirmar a publicação. Consulte o vídeo atual antes de repetir o envio.'};}if(xhr.status<200||xhr.status>=300){status.textContent=data.error||'Não foi possível publicar o vídeo.';release();return;}try{const saved=await refresh();if(!saved.configurado||saved.atualizado_em!==data.atualizado_em)throw Error('O envio terminou, mas a confirmação não corresponde ao vídeo publicado. Atualize esta consulta.');status.textContent='Vídeo publicado. A chamada do site já usa o novo arquivo; clicar na imagem inicia a reprodução.';form.reset();preview.pause();preview.removeAttribute('src');preview.hidden=true;if(localPreview)URL.revokeObjectURL(localPreview);}catch(error){status.textContent=error.message;}finally{release();}};
  xhr.onerror=()=>{status.textContent='A conexão foi interrompida. Consulte o vídeo atual antes de tentar novamente.';release();};xhr.ontimeout=xhr.onerror;xhr.timeout=600000;xhr.send(file);
 });
 refresh().catch(error=>status.textContent=error.message);
 return{refresh:()=>refresh().catch(error=>status.textContent=error.message)};
}
